            # Log the error with full traceback
            logging.error(
                f"Unexpected error during order cancellation for reservation ID {reservation_id}. "
                f"Reference code: {ref_code}",
                exc_info=True
            )

            # Construct user-facing message
            return (500, f"An unexpected error occurred. Please try again later. (Ref: {ref_code})")

    def orders_placed(self) -> int:
        """Return the count of successfully placed orders."""
        return self._orders_placed
